NAME = 'PohnOld: Old Public Domain Pohnpeian Bible'
BOOK = 'Galatians'

CHAPTERS = {
    1: {
        1: 'PAULUS wanporon amen kaidin sang ren aramas akan, pil kaidin pan aramas akan, a pan Iesus Kristus o Kot Sam, me kotin kaiasadar i sang ren me melar akan,',
        2: 'O ri atail akan karos, me mi re i, at ranamau ong momodisou en Kalesia kan:',
        3: 'Mak o popol sang ren Kot Sam o atail Kaun Iesus Kristus en mi re omail;',
        4: 'Me kotin sokonpaude ki pein i ki dip atail, pwen dore kitail sang ni me sued akan mi sappa, duen kupur en Kot o Sam atail.',
        5: 'Lingan en ko ong i kokolata! Amen.',
        6: 'I puriamuiki omail madang wuki sang i, me molipe komail pan mak en Kristus, ap wuki ong eu rongamau;',
        7: 'A sota eu mia. Ari so, akai mia, me kin kapingada komail, o irail men kalikame rongamau en Kristus.',
        8: 'A ma kit de tounlang amen sang nanlang pan padaki ong komail eu rongamau, me toror sang rongamau, me se padaki ong komail er, i en riala.',
        9: 'Duen me se indada mas o, iduen se pil purong inda: Ma amen pan padaki ong komail eu rongamau, me toror sang me komail aleer, i en riala.',
        10: 'Iaduen, i kin men kaperenda aramas akan de Kot? De i kin rapaki konekon ren aramas akan? Ma i men konekon ren aramas akan, i ap sota ladun Kristus.',
        11: 'I katitiki ong komail ri ai kan, rongamau me i padakier, a sota tapi sang ren aramas.',
        12: 'Pwe i sota ale sang ren aramas amen, o sota me padaki ong ia, a a koki dong ia kasale pan Iesus Kristus.',
        13: 'Pwe komail ronger duen ai wiawia en mas nan pung en men Sus akan, duen i kin morouo ong momodisou en Kot lapalapia o kawe ir ala.',
        14: 'O i kakairida nin lamalam en Sus akan madang sang me toto, me kit ti ta ieu o toun sap ta ieu, o i nantiong kapwaiada padok en sam at akan.',
        15: 'A Kot lao kupureda, me kotin kilele ia di sang ni kaped en in ai, o me kotin molipe ia ki a mak,',
        16: 'En kasale ong ia sapwilim a Ol, pwe i en padaki ong men liki kan duen i, i ap pitipit wiada o sota kalelapok ren uduk o nta.',
        17: 'O i pil so pwar lang Ierusalem ren irail, me wanporon akan mo i, a i kolang Arapien ap pil pure dong Damaskus.',
        18: 'Ari, murin par silu i ap kodalang Ierusalem, pwen kilang Kepas. I ap mimieta re a ran eisoklimau.',
        19: 'A sota amen ren wanporon akan, me i kilang, Iakopus ta, ri en Kaun o.',
        20: 'A me i inting wong komail, Kot me kotin mangi, me i sota likam.',
        21: 'Muri i ap kola nan wein Sirien o Silisia.',
        22: 'A momodisou en Iudäa kan me mi pan kupur en Kristus sasa ia.',
        23: 'A i eta, irail ronger, me i me kin morouo ong kit mas o, i me kin padaki poson ansau wet, me a kin kaokaoe mas o.',
        24: 'Irail ap kalinganda Kot pweki ngai.',
    },
    2: {
        1: 'KADEKADEO murin par eisok paieu ngai pil kodalang Ierusalem iang Parnapas o Titus pil iang ia.',
        2: 'A i kokidala kasalepa eu; padaki ong irail duen rongamau, me i kin padaki ong men liki kan, ap katoror ong ir, me kalok mau, pwe i ender tang mal, ma met de mur.',
        3: 'A pil Titus, me iang ia, men Krik amen, re sota kakaliki ong i, en sirkomsaisela,',
        4: 'A pweki akai saulang likam, me wailong, pwen masamasan at saledokalar, me se aleer ren Kristus Iesus, pwen kalidui kit ala.',
        5: 'A se sota man peiki ong irail, pwe melel en rongamau en mimieta re omail.',
        6: 'A irail me kalok mau, i sota asa duen ar tiak en mas o, a pil menda re i, pwe Kot sota kin lipilipil aramas amen, irail me indand mau, sota ki ong ia eu padak toror.',
        7: 'A irail lao kilanger, me i aleer ai koa, en padaki ong me sosirkomsais rongamau, dueta Petrus ong me sirkomsais.',
        8: 'A me kamanada Petrus, pwen kapwaiada a koa en wanporon ren sirkomsais i me i pil keleki ni ai dodok ren men liki kan.',
        9: 'A Iakopus, o Kepas, o Ioanes, me re wiaki ur oko, re lao kilanger mak o me i aleer, rap itipa ki ong ngai o Parnapas pali maun en pa, o kit karos wiaki eu, me kit en kola ren men liki kan, a irail ren sirkomsais.',
        10: 'A re kakaliki ong kit, me sen apapwali me samama kan. Ngai ari nantiong kapwaiada.',
        11: 'A Kepas lao pwaralang Antiokien, i ap palian i pwe kalok sued mi re a.',
        12: 'Pwe mon akai pwarado sang ren Iakopus, a sakasak ren men liki kai, a ni ar pwarador, a puei sang katororela pein i, pwe a masak men sirkomsais.',
        13: 'O pil Sus tei ko iang i malamalaundar, o Parnapas lodi ong pil wia malaun.',
        14: 'A ni ai kilanger, me re sota inen weita, duen melel en rongamau, i ap indai ong Kepas mon irail karos; ma koe men Sus amen kin wia tiak en men liki kan, a so tiak en men Sus, menda koe kin kakaliki ong men liki kan, ren wiada tiak en men Sus?',
        15: 'Kita udan men Sus a sota dipan dueta men liki kan,',
        16: 'Ap asa, me aramas amen sota kak pung kila wiawia en kapung kan, pwe a poson Iesus Kristus eta i me kitail pil posoneki Kristus Iesus, pwe kitail en pung kila poson Kristus, a kaidin wiawia en kapung kan; pwe uduk sota kak pung kila wiawia en kapung kan.',
        17: 'A ma kitail men pung kila Kristus, ap diarokada, me kitail me dipan, daduen, Kristus me papan dip? O so!',
        18: 'Pwe ma i pan pur ong kauada, me i kawelar, nan i pan wia kin ia me dipan amen.',
        19: 'Pwe i mekilar kapung, ap solar memauri ong kapung, pwen mauri ong Kot; ngai lopular iang Kristus.',
        20: 'Kaidin ngai me memaur, pwe Kristus kotin ieiasata lolei. Pwe arain ai maur en pali uduk, i kin memaureki poson Sapwilim en Kot, me kotin pok ong ia o sokonpaudeki ong ia pein i.',
        21: 'I sota kasamal la mak en Kot; pwe ma aramas kak pung kila wiawia en kapung kan, Kristus ap matala mal.',
    },
    3: {
        1: 'O komail men Kalesia pweipwei, is me kotaue komail? Pwe mom en Iesus Kristus a lopular wiauier mon mas omail.',
        2: 'Iet eta me i men kalelapok re omail: Komail aleer Ngen ni wiawia en kapung kan, de ni padak en poson?',
        3: 'Iduen omail lolepon? Komail tapia kidar Ngen, a komail men kaimwisok kilar uduk?',
        4: 'Komail kalokolok laud, ap sota pan katepa? Ma idue met a sota kak wiaui.',
        5: 'Me kotiki ong komail er Ngen, o wia manaman akan nan pung omail daduen, wiawian kapung kan me kareda, de padak en poson?',
        6: 'Dueta Apraam me poson Kot, ap wadok ong i kapunga pa.',
        7: 'Komail ap asa duen irail me kin poson, irail seri en Apraam.',
        8: 'A kisin likau o asaer mas o, me Kot, pan kotin kapungala men liki kan ki poson, i me a padaki ong Apraam rongamau mas o: Wein sappa karos pan paie kin uk!',
        9: 'Pwe karos me poson, pan iang Apraam poson kapaida.',
        10: 'Pwe me kin kaporoporeki wiawia en kapung kan, pan kariala. Pwe a intingidier: Karos me riala, me sota pan dadaurata meakaros, me intingidier nan puk en kapung, pwen kapwaiada.',
        11: 'A sansal, me sota amen kak pung kila kapung ren Kot; pwe me pung amen pan memaureki poson.',
        12: 'A kapung sota tapi sang ni poson, pwe meamen kapwaiada mepukat, pan memaur kida.',
        13: 'Kristus me kotin dore kitail sang ni karia pan kapung, ni a ria kin kitail lar; pwe a intingidier: Amen amen me langalong nin tuka o me riala.',
        14: 'Pwe pai en Apraam, me tapi sang ren Kristus Iesus, en lel penang men liki kan; pwe kitail en ale inau en Ngen ki poson.',
        15: 'Ri ai kan, i pan lokaia ni tiak en aramas akan. Iaduen inau en aramas eu me kileledier, sota amen me pan kawela de ekis, me a pan pouse ong.',
        16: 'Ari, inau o wiauier ong Apraam o kadaudok a. A sota masanier: Kadaudok a toto, pwe duen me ta men: Kadaudok om me ta men, iei Kristus.',
        17: 'Iet me i inda: Inau me Kot kotin kileledier, a sota kak okila kapung o, me wiauier saunpar papuki sileisok murin inau o, pwe inau ede pwaida.',
        18: 'Pwe ma soso tapi sang kapung, a sota kak tapi sang inau; a Kot kotiki ong Apraam ki inau.',
        19: 'A menda kapung? A wiauier pweki sapung kan, kadaudok o lao pwarado, me inau wiaui ong, me wiauier ren tounlang kan ki pa en saunkapung.',
        20: 'Ari, saunkapung sota kin kelep eta, a Kot me kelep eta.',
        21: 'A iaduen, kapung o kin palian inau en Kot akan? O so! A ma kapung eu pan wiaui, me pan kak kamaurela, nan melel, pung ap pan tapi sang nan kapung.',
        22: 'A kisin likau o me kol penang dip meakaros pwe inau en tapi sang ni poson Iesus Kristus, en pai ong irail, me poson.',
        23: 'Ni ansau poson saikenta pwarado, kitail nikinik o salidier pan kapung, lao poson pan kasansaleda.',
        24: 'Ari, kapung atail saunpadak, lao Kristus pwarado, pwe kitail en pung kila poson.',
        25: 'A poson lao pwarador, kitail solar mi pan saunpadak o.',
        26: 'Pwe komail karos seri en Kot, ki poson Kristus Iesus.',
        27: 'Pwe komail me paptaiser ong Kristus, komail likaui kidar Kristus.',
        28: 'Solar men Sus de Krik, solar ladu de me maioda, solar ol de li komail karos dupeneta ren Kristus Iesus.',
        29: 'A ma komail sapwilim en Kristus, nan komail pil kadaudok en Apraam, o seri soso duen inau o.',
    },
    4: {
        1: 'A iet me i men inda: Soso men arain a seri, a so toror sang ladu men, ari so, a kaun en meakaros.',
        2: 'A kin upa ong saunpadak o saunkoa kan lao lel ansau me sam a kileledier.',
        3: 'Iduen kitail ni atail kisin seri, kitail kin upai ong padak en sappa kan.',
        4: 'A ansau lao leler, Kot ap kotin poronedo sapwilim a Ol, me ipwidi sang ren li amen, ap mi pan kapung o.',
        5: 'Pwen kasaledoka ir ala, me mi pan kapung, pwe kitail en wiala sapwilim a seri.',
        6: 'Komail ari seri kan, i me Kot ap kotin poronedo Ngen en sapwilim a Ol nan mongiong atail, me kin likelikwir: Apa Sam!',
        7: 'Ari, solar ladu men, pwe seri ta; a ma seri nan pil seri soso en Kot.',
        8: 'A ni ansau o me komail sasa Kot, komail papaer me kaidin udan kot akan.',
        9: 'A metet komail asalar Kot, o Kot me kotin mangi komail melel, menda komail pil sapal lang lamalam sued o sakanekan, me komail men pur ong papa?',
        10: 'Komail kin kasarauiela ran akai, o saunipong kai, o ansau kai, o saunpar kai.',
        11: 'I ngong kin komail, pwe ele ai dodok ong komail sota pan kadepa.',
        12: 'Ri ai kan, i ngidingidi kin komail, en dueta ngai, pwe ngai kin dueta komail, pwe sota me sued kot, me komail wiai ong ia er.',
        13: 'A komail asa due i mas o, me i padaki ong komail er rongamau ni ai luet en pali uduk.',
        14: 'O komail sota mamaleki ai songesong ni uduk ai o tata kin ia; a komail apwali ia la dueta ngai tounlang en Kot amen, de dueta Iesus Kristus.',
        15: 'Iaduen wan omail pai ni ansau o! Pwe i kadede duen komail, ma a kak pa omail, komail pan pwadika sang por en mas omail ap ki ong ia.',
        16: 'Iaduen, i wiala omail imwintiti, pweki ai lokaia melel ong komail.',
        17: 'Arail nanantiong rapaki komail me sota mau; irail men kamueit kitail pasang, pwe komail en id idauen irail.',
        18: 'Me mau ansau karos en nantiong me mau kan, a kaidin ta ni ai mi re omail.',
        19: 'Nai seri kan! I naitik sapal komail ki madak, lao Kristus kawuk komail la ong pein mom a.',
        20: 'I men mi re omail ansau wet o men kawukila ngil ai, pwe i sasalar ir omail.',
        21: 'Komail, me kin men mi pan kapung o, indang ia, ma komail sota kin rong kapung o?',
        22: 'Pwe a intingidier, me nain Apraam putak riamen mia, amen sang ren na lidu, a amen sang ren me maioda.',
        23: 'A me song ren lidu ipwiki uduk, a me sang ren me maioda, ipwiki inau en Kot.',
        24: 'Mepukat karasepa eu, pwe met inau riau, eu sang ni nana Sinai, me kin naitiki ong na kan papa, i me Akar.',
        25: 'Pwe Akar nana Sinai nan Arapien, me rasong Ierusalem en met, o kin lidilidui iang na seri kan.',
        26: 'A Ierusalem, me mi poa, me maioda iei in atail.',
        27: 'Pwe a intingidier: Pereperen koe me li dapwan, me sota kin naitik, kadailong o werida koe, me so kaipwi ong, pwe nain li dapwan seri kan me toto sang me a warok mia.',
        28: 'A komail ri ai ol akan, me rasong Isaak, me seri en inau kan.',
        29: 'A duen mas o, me ipwiki uduk, me kailongki me ipwiki Ngen o, iduen ansau wet.',
        30: 'A da me kisin likau o masani? Kasela li lidu o na putak! Pwe putak en lidu sota pan iang nain li me maioda sosoki.',
        31: 'Ari ri ai kan, kitail sota seri en lidu, pwe nain me maioda.',
    },
    5: {
        1: 'KOMAIL ari dadaurata en Kristus a kotin kamaioda kitail, komail ari kalaka pein komail, pwe komail der pur ong ni omail kanaudok.',
        2: 'Kilang, ngai Paulus indai ong komail, ma komail pan iang sirkomsais, nan Kristus sota pan katepai ong komail.',
        3: 'I pil kadede ong aramas karos, me pan sirkomsaisela, i en kapwaiada kapung pokon.',
        4: 'Komail, me men pung kila kapung o, muei sanger Kristus o pup wei sanger mak.',
        5: 'A kit kin auiaui ren Ngen ki poson kaporopor en pung.',
        6: 'Pwe ren Kristus Iesus sirkomsais de sosirkomsais sota meakot, pwe poson ta, me kin sansaleki dodok en limpok.',
        7: 'Komail tanger mau, is me karompwa komail, pwe ender peiki ong melel?',
        8: 'I song en kaweid sota kin tapi sang me molipe komail er.',
        9: 'Kalap kis kin kamutala dolepa karos;',
        10: 'I kaporoporeki ren Kaun o me komail sota pan wia eu lamalam toror. A me kin kaping komail da, pan lodi ong kapung o, sota lipilipil is i.',
        11: 'A ngai, ri ai kan, ma i poden padaki duen sirkomsais, menda i kankangerangirla? Pwe ma iduen, a solar men kamakar pan lopu.',
        12: 'I men irail me kin kawe komail la, ren pil kawela pein irail.',
        13: 'A ri ai kan, komail paeker ong maio, komail der men maio, pwe tiak en pali uduk en pwaida, a komail papa amen amen ni limpok.',
        14: 'Pwe kapung pon kapwai pan masan ta ieu: Koe en pok ong men imp om due pein uk.',
        15: 'A ma komail pakolok kaokaoe amen o amen, kalaka, pwe komail de momela.',
        16: 'A ngai inda: Aluki Ngen komail ap sota pan kapwaiada inong sued en uduk.',
        17: 'Pwe uduk kin inong iong me toror sang Ngen, a Ngen kin kotin inong iong me toror sang uduk, a ira parongarong pena, iei me komail sota wia kida, me komail kin men wia.',
        18: 'A ma Ngen pan kotin kalua komail, komail sota mimi pan kapung.',
        19: 'Wiawia kan en uduk me sansal. Iet akan: Nenek, samin, monepil,',
        20: 'Pongi ong ani mal, wun ani, kailuk, akatat, luak, makar, akamai, kamauouo, padak likam.',
        21: 'Peirin, kamom soko, kaped en manga ape. Iran mepukat i padaki ong komail er mas o, me irail, me kin kapwaiada mepukat, sota pan sosoki wein Kot.',
        22: 'A iet akan wa en Ngen: Limpok, peren, popol, kanongama, kadek, kamau, poson, opampap liki sang me sued.',
        23: 'Sota kapung pan mepukat.',
        24: 'A me sapwilim en Kristus, kalopuelar uduk iangaki tiak sued o inong sued akan.',
        25: 'Ma kitail memaureki Ngen, kitail en pil alualuki Ngen o.',
        26: 'Kitail der inong iong wau ren aramas, o der kamorongada ong amen amen, o der peipeirin amen amen.',
    },
    6: {
        1: 'RI ai kan ma aramas amen pan lodi ong me sued kot, komail, me ngenin kasapaledo i ni ngen en opampap, ap masamasan pein uk, pwe koe ender pil lodi ong songesong.',
        2: 'Pelikitki pena nan pung omail katoutou pamail, pwe iduen komail pan kapwaiada kapung en Kristus.',
        3: 'Pwe ma amen lamelame, me i meakot, nan a kin kotaue pein i, pwe sota i meakot.',
        4: 'A amen amen en kasasong ong pein a wiawia, ap pan suaiki pein i, a kaidin amen aramas.',
        5: 'Pwe amen amen en pein wa audepa.',
        6: 'A me kin padakki masan o, en kida song en mau karos ong i, me kin padaki i.',
        7: 'Komail der kiki ong, me komail pan kak piti Kot, pwe meakot aramas kin kamoredi ong, i me a pan dolung sang.',
        8: 'Pwe me kin kamoredi ong ni uduk a, a pan dolung sang ni uduk a men soredi; a me kin kamoredi ong Ngen, a pan tungole sang ren Ngen maur soutuk.',
        9: 'Kitail der pangaki atail wiawia mau kan, pwe ni ansau me kon ong, kitail pan dolung, ma kitail sota pan pangadar.',
        10: 'Ma a kak pa atail, kitail en wia mau ong karos, a mas ong kisan me poson akan.',
        11: 'Kilang duen kisin likau laud, me i inting wong komail er ki pein pa i.',
        12: 'Ir me kin men lolok mau ni uduk, kin inong iong komail en sirkomsaiselar; pwe irail ender kamekame ki lopu en Kristus.',
        13: 'Pwe pein irail me sirkomsaisela, sota kin kapwaiada kapung, a irail kin men, komail en sirkomsaisela, pwen suaiki uduk omail.',
        14: 'A duen ngai, i sota man mauki suaiki, a iet eta iran lopu en atail Kaun Iesus Kristus, pweki i sappa katia sang ia o ngai katia sang sappa.',
        15: 'Pwe sirkomsais de sosirkomsais sota meakot, a me kawilikapadar.',
        16: 'Irail karos me inen ki wei ta padak pot et, en popol o kalangan, o ong Israel en Kot.',
        17: 'Sang met kokolata sota amen en morouo ong ia, pwe i wa sili ta nan war ai lip en Iesus akan.',
        18: 'Mak en atail Kaun Iesus Kristus en kotikot ren ngen omail ri ai kan! Amen.',
    },
}
